INSERT INTO programs (title, description, category, icon, image_url, display_order, active) VALUES
('Ubuntu University', 'A Pan-African institution of higher learning dedicated to nurturing Africa''s brightest minds. Ubuntu University will offer world-class education rooted in African values, producing leaders who serve their communities with integrity and innovation.', 'future', 'GraduationCap', NULL, 100, true),
('Ubuntu Hospital', 'A state-of-the-art healthcare facility providing accessible, quality medical care across the continent. Ubuntu Hospital will combine modern medicine with community health approaches to serve those who need it most.', 'future', 'Hospital', NULL, 101, true),
('UTU Disaster Relief Arm', 'A rapid-response humanitarian unit embedded within each UTU Wakiafrika country branch. This arm mobilizes local volunteers and resources to provide immediate aid and long-term recovery support to communities affected by natural disasters and crises.', 'future', 'ShieldAlert', NULL, 102, true),
('Ubuntu — Africa''s Social Media', 'A homegrown digital platform built for Africans, by Africans. Ubuntu Social Media will celebrate African culture, foster continental connections, and provide a safe, empowering space for storytelling, commerce, and community building across the continent.', 'future', 'Share2', NULL, 103, true),
('Ubuntu Technologies', 'A tech enterprise building transformative digital products for Africa — from global payment systems enabling seamless cross-border transactions, to infrastructure solutions that power businesses and governments across the continent.', 'future', 'Cpu', NULL, 104, true);
